import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { validatePublishableSnapshotContent } from '@hattz/validation';

// The fixture is the single source of truth shared with the SQL side
// (infrastructure/supabase/validation/sql/30_validator_parity.sql). Both files are
// generated by infrastructure/supabase/validation/parity/build_parity.mjs, so the
// TypeScript and PostgreSQL validators are exercised against exactly the same inputs.
interface ParityCase {
  id: string;
  expect: boolean;
  content: unknown;
  sql?: string;
}

const fixture = JSON.parse(
  readFileSync(resolve(process.cwd(), 'tests/fixtures/publishable-snapshot-parity.json'), 'utf8'),
) as { cases: ParityCase[] };

describe('publishable snapshot validation — SQL/TS parity fixture (generated)', () => {
  it('has a non-trivial fixture (guards against an empty/truncated generator output)', () => {
    expect(fixture.cases.length).toBeGreaterThan(50);
    const ids = new Set(fixture.cases.map((c) => c.id));
    expect(ids.size).toBe(fixture.cases.length);
  });

  it('TypeScript validator matches the expected result for every parity case', () => {
    const mismatches = fixture.cases
      .map((c) => {
        const res = validatePublishableSnapshotContent(c.content);
        return { id: c.id, expect: c.expect, got: res.ok, issues: res.issues };
      })
      .filter((r) => r.got !== r.expect);

    expect(
      mismatches.map(
        (m) =>
          `${m.id}: expected ${m.expect} got ${m.got} (${m.issues.map((i) => i.code).join(',')})`,
      ),
    ).toEqual([]);
  });
});
